INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
  (13972, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (13978, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (13984, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (13994, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14002, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14015, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14020, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14026, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14027, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14029, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14078, 4, 0, 0, 0, 0, 0, 0, 0, 'Deep claw marks run through the man''s corpse.', 0),
  (14091, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s you again.  Looks like you''re not one to hide in the face of danger.  Very well, then.', 0),
  (14093, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s no use, $N!  They''re not letting up.', 0),
  (14094, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent!  I''ll make sure these get taken to a safe place.', 0),
  (14097, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14098, 4, 0, 0, 0, 0, 0, 0, 0, 'Good job, $N.  Thanks to you, many Gilneans will live to see another day.', 0),
  (14099, 4, 0, 0, 0, 0, 0, 0, 0, 'We''re all fine here.  A little shaken... but alive.', 0),
  (14154, 4, 0, 0, 0, 0, 0, 0, 0, 'We did it, $N.  Thanks to you a good man has survived.', 0),
  (14157, 4, 0, 0, 0, 0, 0, 0, 0, 'Greymane wants to save Crowley?  Has he gone mad?', 0),
  (14159, 4, 0, 0, 0, 0, 0, 0, 0, 'Don''t look at me!  Leave me alone!', 0),
  (14204, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent.  I''ll start rounding up some help to get these cannons positioned.', 0),
  (14212, 4, 0, 0, 0, 0, 0, 0, 0, 'Brace yourself, $N.$B$BHere they come.', 0),
  (14214, 4, 0, 0, 0, 0, 0, 0, 0, 'I knew Crowley would come through.  His weapons will be more than useful to us.', 0),
  (14218, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well, $N.  You''ve done more than could be asked of any Gilnean.$B$BWe''re running low on ammunition.  It''s time to regroup inside now.', 0),
  (14220, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14221, 4, 0, 0, 0, 0, 0, 0, 0, 'We''ve given them everything we have... yet still they come.  Do not worry, $N.  We''ll slay many more before today is over.', 0),
  (14222, 4, 0, 0, 0, 0, 0, 0, 0, 'They... they''ve stopped coming.$B$BNo, $N.  That''s not a good thing.', 0),
  (14265, 4, 0, 0, 0, 0, 0, 0, 0, '$N!  Where have you been?$B$BAnyway... it''s great to see you in one piece.', 0),
  (14266, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent work!', 0),
  (14269, 4, 0, 0, 0, 0, 0, 0, 0, 'Oh, hey!  There you are!', 0),
  (14272, 4, 0, 0, 0, 0, 0, 0, 0, 'Don''t get ahead of yourself now.  Just remember who taught you everything you know.$B$BAnd now let''s see if we can get out of this city with our skins attached.', 0),
  (14273, 4, 0, 0, 0, 0, 0, 0, 0, 'A darkness has descended over our lands.  And not our kind of darkness, if you know what I mean.', 0),
  (14274, 4, 0, 0, 0, 0, 0, 0, 0, 'Yes!  You can feel the power, can''t you?', 0),
  (14275, 4, 0, 0, 0, 0, 0, 0, 0, '$n!  I knew you had to be around here.', 0),
  (14276, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent work, $n.  These $r will regret ever setting foot in our lands.', 0),
  (14277, 4, 0, 0, 0, 0, 0, 0, 0, 'A disciple of the arcane always finds a way forward. I''m glad to see you, $N.', 0),
  (14278, 4, 0, 0, 0, 0, 0, 0, 0, 'The Light is with you, $n.  It''s still quite a relief to see you.', 0),
  (14279, 4, 0, 0, 0, 0, 0, 0, 0, 'You are blessed, $n.  The Light shines upon you, even in these dark times.', 0),
  (14280, 4, 0, 0, 0, 0, 0, 0, 0, 'We have been blessed today!  You are alive and well!', 0),
  (14281, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve learned with such speed and ease. Soon you''ll be the one doing the teaching.', 0),
  (14283, 4, 0, 0, 0, 0, 0, 0, 0, 'Not bad at all.  Perhaps there is still hope for the old ways.', 0),
  (14285, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14286, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14287, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14288, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here. If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14289, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14290, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14291, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well in coming here.  If we Gilneans stick together we might yet defeat this terrible enemy.', 0),
  (14293, 4, 0, 0, 0, 0, 0, 0, 0, 'Well done, $N.  We''ll make sure Krennan makes it out of the city alive.', 0),
  (14294, 4, 0, 0, 0, 0, 0, 0, 0, 'We''re left with very few choices, $N.  What we do next will be a critical decision.', 0),
  (14313, 4, 0, 0, 0, 0, 0, 0, 0, 'It worked!  By the Light, it worked!', 0),
  (14317, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14319, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14320, 4, 0, 0, 0, 0, 0, 0, 0, 'The crate has been smashed and the vials inside of it appear to have been broken.', 0),
  (14321, 4, 0, 0, 0, 0, 0, 0, 0, 'Forsaken!  Quick, $N!  We must mount a defense.', 0),
  (14336, 4, 0, 0, 0, 0, 0, 0, 0, '$N!!!  You ARE alive!$B$BI thought I was having dreams about the old days when I heard your voice...', 0),
  (14347, 4, 0, 0, 0, 0, 0, 0, 0, 'Yes, $N!  Just like old times...$B$BI''m going to have to work hard at not shooting you, but Krennan explained everything to us.', 0),
  (14348, 4, 0, 0, 0, 0, 0, 0, 0, 'You and me, $N.  We make a great team...$B$BIt''s good to have you back.', 0),
  (14366, 4, 0, 0, 0, 0, 0, 0, 0, 'Great news, $N.  I''ve sent the remaining militia to the shore to meet the Forsaken force head on.', 0),
  (14367, 4, 0, 0, 0, 0, 0, 0, 0, 'The Forsaken are here in full strength, $N.  We barely have enough men to hold them back.', 0),
  (14368, 4, 0, 0, 0, 0, 0, 0, 0, 'My children are safe!  You''ve done a wonderful thing, $N.  I don''t know how to thank you!', 0),
  (14369, 4, 0, 0, 0, 0, 0, 0, 0, 'Not bad, $N.  It''s a good thing you''re on our side.', 0),
  (14375, 4, 0, 0, 0, 0, 0, 0, 0, 'I need you to pull through, $N.  This dosage is strong enough to kill a horse.$B$BBut I know you.  I know what you''re made of.  You will be fine.$B$BTrust me.  I know what you''re going through.$B$BNow drink up and close your eyes.', 0),
  (14382, 4, 0, 0, 0, 0, 0, 0, 0, 'Well done, $N.  You might be a bloody beast, but you''re our beast.', 0),
  (14386, 4, 0, 0, 0, 0, 0, 0, 0, 'You did it, $N.  That should take the wind out of their sails.', 0),
  (14395, 4, 0, 0, 0, 0, 0, 0, 0, 'You did what you could, $N.  With any luck a few others will find their way to shore.', 0),
  (14396, 4, 0, 0, 0, 0, 0, 0, 0, 'The ocean, $N.  It swallowed everything... the land... the Forsaken... our men!', 0),
  (14397, 4, 0, 0, 0, 0, 0, 0, 0, 'Liam is right.  We must get everyone to higher ground.$B$BYou must help me spread the word while I manage the logistics of the evacuation.', 0),
  (14398, 4, 0, 0, 0, 0, 0, 0, 0, 'A visitor!  Are you staying for tea, sweetheart?', 0),
  (14399, 4, 0, 0, 0, 0, 0, 0, 0, 'Why thank you, $N.  I hope you didn''t peek!$B$BWhere are your manners, dear?', 0),
  (14400, 4, 0, 0, 0, 0, 0, 0, 0, 'You''re a peach, $N.  Thanks!', 0),
  (14401, 4, 0, 0, 0, 0, 0, 0, 0, 'There he is!  Grandma''s special boy!$B$BThank you so much for finding him.  I hope it wasn''t too much trouble.$B$BMy... what manner of dirt found its way underneath my fingernails!', 0),
  (14402, 4, 0, 0, 0, 0, 0, 0, 0, 'You did the impossible, $N. You convinced Grandma Wahl to leave her home.$B$BYou are something else, let me tell you.', 0),
  (14403, 4, 0, 0, 0, 0, 0, 0, 0, 'You here to give us a hand?', 0),
  (14404, 4, 0, 0, 0, 0, 0, 0, 0, 'This is great, $N.  I should be able to finish the repairs in no time.', 0),
  (14405, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s just as well, $N.  Maybe the Haywards will fare better than us.', 0),
  (14406, 4, 0, 0, 0, 0, 0, 0, 0, 'Stay back! Don''t make me...$B$BIs it you?  By the Light!  It''s you, $N!', 0),
  (14412, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent!  I''m almost done here.', 0),
  (14415, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (14416, 4, 0, 0, 0, 0, 0, 0, 0, 'We''ve got the horses, I''ll make sure Duskhaven gets them.', 0),
  (14434, 4, 0, 0, 0, 0, 0, 0, 0, 'Nice to see you again, $n. We did it!', 0),
  (14463, 4, 0, 0, 0, 0, 0, 0, 0, 'Excellent work, $N.  I think I speak for everyone when I say the sooner we get out of here, the better.', 0),
  (14465, 4, 0, 0, 0, 0, 0, 0, 0, '$N.  I''ve heard much about you.$B$BI understand you were crucial in my family''s survival during the outbreak in Gilneas City.', 0),
  (14466, 4, 0, 0, 0, 0, 0, 0, 0, 'There you are, $N.  I''ve been expecting you.$B$BI got word of your recovery and... wait -- do you feel that?', 0),
  (14467, 4, 0, 0, 0, 0, 0, 0, 0, 'Look, $N!  Look at what''s become of Duskhaven!$B$BLook at what''s become of the last safe place in Gilneas!', 0),
  (24438, 4, 0, 0, 0, 0, 0, 0, 0, 'Thanks for stopping, $N.  Our carriage got hit pretty bad.$B$BThe one in front of us got it worse.', 0),
  (24468, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done it again, $N.  You have my thanks.', 0),
  (24472, 4, 0, 0, 0, 0, 0, 0, 0, 'You definitely got the ettin angry, $N.   I heard him myself.$B$BLet''s hope this works.', 0),
  (24483, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s good to see you made it, $N.  It looks like most everybody did.$B$BWe''re not doing too bad so far for an emergency evacuation.', 0),
  (24484, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well, $N.  The spiders are everywhere, however, and I''m afraid we''ve barely put a dent in their numbers.', 0),
  (24495, 4, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $N.  It will take some time, but I''ll try to make sense of what we have.', 0),
  (24501, 4, 0, 0, 0, 0, 0, 0, 0, 'Great job, $N.  We''ve heard rumors of survivors further in the mountains.  Now we''ll be able to send scouts there.', 0),
  (24575, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done it again, $N.  The freed villagers are eager to help us against the Forsaken in any way they can.', 0),
  (24578, 4, 0, 0, 0, 0, 0, 0, 0, 'I''ve been expecting you, $N.  Do not be alarmed.$B$BMy name is Belysra.  I am a priestess of the moon... a night elf.$B$BYou might not know my people, but the destinies of our two races have been linked since the Curse befell you.', 0),
  (24592, 4, 0, 0, 0, 0, 0, 0, 0, 'I wish it could''ve been avoided, $N.  Let us ensure this is resolved without further bloodshed.', 0),
  (24593, 4, 0, 0, 0, 0, 0, 0, 0, 'It is done then, $N.  You are one of us now.', 0),
  (24602, 4, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $N.  Let us hope this works.', 0),
  (24616, 4, 0, 0, 0, 0, 0, 0, 0, 'Well done, $N.  The scout never had a chance.', 0),
  (24617, 4, 0, 0, 0, 0, 0, 0, 0, 'You''re all right, $N!  I''ve been waiting for this day for a long time, it truly is great to see you friend.$B$BI''ve heard of what you''ve done and I''m thankful... especially for Lorna -- she''s all I''ve left.  I will send for her right away.', 0),
  (24627, 4, 0, 0, 0, 0, 0, 0, 0, 'You are as good as I remember, $N.  It is good to have you back.', 0),
  (24628, 4, 0, 0, 0, 0, 0, 0, 0, 'These simple leaves grow by Elune''s grace.  They will help your mind understand the need for balance and your soul will permanently earn mastery over the beast.', 0),
  (24646, 4, 0, 0, 0, 0, 0, 0, 0, 'I knew we could count on you.  You''ve done well, $N.', 0),
  (24672, 4, 0, 0, 0, 0, 0, 0, 0, '$N!$B$BGenn... they''ve taken Genn... they''ve taken... our king!', 0),
  (24673, 4, 0, 0, 0, 0, 0, 0, 0, 'King Greymane gave me a brief rundown of the plan before he set off for the Blackwald.  Doesn''t make it sound any less crazy.', 0),
  (24674, 4, 0, 0, 0, 0, 0, 0, 0, 'I thank you, $N.  Our people will no longer suffer under that monstrosity''s yoke.', 0),
  (24675, 4, 0, 0, 0, 0, 0, 0, 0, 'I thank you, $N.  Our men and women will have a last good meal before they set off for battle.', 0),
  (24676, 4, 0, 0, 0, 0, 0, 0, 0, 'We have the people of Emberstone on our side now thanks to you.  ', 0),
  (24677, 4, 0, 0, 0, 0, 0, 0, 0, 'I am glad to have you here, $N.  We''re surrounded by Forsaken on all sides and can use all the help we can get.', 0),
  (24678, 4, 0, 0, 0, 0, 0, 0, 0, 'You''re here, $N.  Most everyone made it through, but now we''re stuck here... surrounded by our own... dead!', 0),
  (24679, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s done, $N.  The dead return to their slumber.', 0),
  (24680, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s good to see you again, $N.', 0),
  (24681, 4, 0, 0, 0, 0, 0, 0, 0, 'It''s almost over, $N.  Only one obstacle remains between us and survival.', 0),
  (24902, 4, 0, 0, 0, 0, 0, 0, 0, 'The Plague?  Something so heinous that not even the orcs condone its use?  I''d say this warrants notifying King Greymane.', 0),
  (24903, 4, 0, 0, 0, 0, 0, 0, 0, 'You present me with the most difficult choice of my life, $N.', 0),
  (24904, 4, 0, 0, 0, 0, 0, 0, 0, 'We''ve driven the Forsaken back.  We hold three out of the four districts.$B$BBut at what cost...', 0),
  (24920, 4, 0, 0, 0, 0, 0, 0, 0, 'You''ve done well, $N.  Almost everybody managed to make it through.  ', 0),
  (24930, 4, 0, 0, 0, 0, 0, 0, 0, 'If I hadn''t seen you kill a few of the mangy things with my own eyes, I''d think you did not complete the task I asked of you.$B$BIt looks like we''re hardly putting a dent in their numbers.', 0),
  (25331, 4, 0, 0, 0, 0, 0, 0, 0, '', 0),
  (26129, 4, 0, 0, 0, 0, 0, 0, 0, 'Rebel arsenals?  In my own city?$B$BWhat in the bloody hell was Crowley up to?', 0),
  (26706, 4, 0, 0, 0, 0, 0, 0, 0, 'We did it, $N.  We''ve started the evacuation.  If we leave soon we''ll leave the Forsaken fleet in the dust.', 0),
  (28850, 4, 0, 0, 0, 0, 0, 0, 0, 'Greymane''s right.  These beasts do not give a damn about our politics.$B$BGilneas needs to stand together.', 0);
